    private void initListeners() {
        // Connect button
        buttonConnect.addActionListener(e -> {
            String ip = fieldIP.getText().trim();
            if (ip.isEmpty()) {
                javax.swing.JOptionPane.showMessageDialog(this, "Please enter an IP address.");
                return;
            }
            new Thread(() -> {
                try {
                    net.connect(ip, 21);
                    // Show auth UI once we have connection
                    javax.swing.SwingUtilities.invokeLater(() -> {
                        Auth UIauth = new Auth(this, net);
                        UIauth.setLocationRelativeTo(this); // Center it over the current form
                        UIauth.setVisible(true);
                    });
                } catch (Exception ex) {
                    javax.swing.SwingUtilities.invokeLater(() -> {
                        javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage());
                    });
                }
            }).start();
        });
        // Disconnect button
        buttonDisconnect.addActionListener(e -> {
            net.disconnect();
            setOnline(false);
            clearFileList();
        });
        // Go To & Refresh Dir buttons combo
        buttonRefresh.addActionListener(e -> updFileList());
        buttonCd.addActionListener(e -> {
            String cdir = fieldPath.getText();
            try {
                file.sendFileOp("cd", cdir);
            } catch (Exception ex) {
                javax.swing.SwingUtilities.invokeLater(() -> {
                    javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage());
                });
            }
            updFileList();
        });
        // Transfer buttons
        buttonUpload.addActionListener(e -> {
            // We bring up the OS native file picker to reduce implementation complexity
            javax.swing.JFileChooser osfpicker = new javax.swing.JFileChooser();
            osfpicker.setFileSelectionMode(javax.swing.JFileChooser.FILES_ONLY);
            osfpicker.setDialogTitle("Select File to Upload");
            int result = osfpicker.showOpenDialog(this);

            if (result == javax.swing.JFileChooser.APPROVE_OPTION) {
                java.io.File f = osfpicker.getSelectedFile();
                String flocal = f.getAbsolutePath();
                String fname = f.getName();
                new Thread(() -> {
                    try {
                        // Autocorrect destination path
                        String cwd = fieldPath.getText().trim();
                        String fremote = cwd + (cwd.endsWith("/") ? "" : "/") + fname;
                        // Initiate the transfer
                        file.transfer("put", flocal, fremote);
                        // Show dialogue when done
                        javax.swing.SwingUtilities.invokeLater(() -> {
                            javax.swing.JOptionPane.showMessageDialog(this, "Upload completed!");
                            updFileList();
                        });
                    } catch (Exception ex) {
                        javax.swing.SwingUtilities.invokeLater(() -> {
                            javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage(), "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
                        });
                    }
                }).start();
            }
        });
        buttonDownload.addActionListener(e -> {
            // Like above, but for this we also need to grab what the user has selected for downloading
            int tfSelectedRow = tableFile.getSelectedRow();
            if (tfSelectedRow == -1) {
                javax.swing.JOptionPane.showMessageDialog(this, "Please select a file from the list to download.", "No file selected!", javax.swing.JOptionPane.WARNING_MESSAGE);
                return;
            }
            String fname = tableFile.getValueAt(tfSelectedRow, 0).toString();
            
            javax.swing.JFileChooser osfpicker = new javax.swing.JFileChooser();
            osfpicker.setSelectedFile(new java.io.File(fname));
            osfpicker.setDialogTitle("Save Downloaded File As...");
            int result = osfpicker.showSaveDialog(this);

            if (result == javax.swing.JFileChooser.APPROVE_OPTION) {
                String flocal = osfpicker.getSelectedFile().getAbsolutePath();
                new Thread(() -> {
                    try {
                        String cwd = fieldPath.getText().trim();
                        String fremote = cwd + (cwd.endsWith("/") ? "" : "/") + fname;
                        file.transfer("get", flocal, fremote);
                        javax.swing.SwingUtilities.invokeLater(() -> {
                            javax.swing.JOptionPane.showMessageDialog(this, "Download completed!");
                        });
                    } catch (Exception ex) {
                        javax.swing.SwingUtilities.invokeLater(() -> {
                            javax.swing.JOptionPane.showMessageDialog(this,  ex.getMessage(), "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
                        });
                    }
                }).start();
            }
        });
        // New Folder button
        buttonNewFolder.addActionListener(e -> {
            NewFolder nf = new NewFolder(this, this.file);
            nf.setLocationRelativeTo(this);
            nf.setVisible(true);
        });
        // Delete button
        buttonDelete.addActionListener(e -> {
            // Also another selection-based button
            int tfSelectedRow = tableFile.getSelectedRow();
            if (tfSelectedRow == -1) {
                javax.swing.JOptionPane.showMessageDialog(this, "Please select a file from the list to delete.", "No file selected!", javax.swing.JOptionPane.WARNING_MESSAGE);
                return;
            }
            String fname = tableFile.getValueAt(tfSelectedRow, 0).toString();
            boolean isdir = tableFile.getValueAt(tfSelectedRow, 1).toString().trim().equals("<DIR>");
            // We then pass this request the deletion dialog, which will do the deletion for it
            // I know that's not how it should go, but Java's GUI code nature makes doing such really hard
            // Ideally all that dialog should do is return is a boolean signal that then tells this to
            // execute the deletion code in here, but I for the love of my life cannot figure out how to do that properly.
            DeleteDiag del = new DeleteDiag(this, this.file, fname, isdir);
            del.setLocationRelativeTo(this);
            del.setVisible(true);
        });
        // Handling for closing the app
        this.addWindowListener(new java.awt.event.WindowAdapter() {
            @Override
            public void windowClosing(java.awt.event.WindowEvent evt) {
                new Thread(() -> {
                    if (connected) { try {
                        // Disconnect from the server so we don't leave it hanging with a ghost session
                        net.disconnect();
                        } catch (Exception ex) {
                            logger.log(java.util.logging.Level.WARNING, "Disconnection on exit may have failed: " , ex);
                        }
                    }
                    java.awt.EventQueue.invokeLater(() -> {
                        dispose(); // Close the UI
                        System.exit(0);  // Finally terminates the application
                    });
                }).start();
            }
        });
    }

    public void onAuth() {
        setOnline(true);
        updFileList();
    }
    private void setOnline(boolean connected) {
        this.connected = connected;
        // Elements to enable when disconnected
        buttonConnect.setEnabled(!connected);
        fieldIP.setEnabled(!connected);
        // Elements to enable when connected
        buttonDisconnect.setEnabled(connected);
        buttonRefresh.setEnabled(connected);
        buttonCd.setEnabled(connected);
        buttonDownload.setEnabled(connected);
        buttonUpload.setEnabled(connected);
        buttonNewFolder.setEnabled(connected);
        buttonDelete.setEnabled(connected);
        fieldPath.setEnabled(connected);
    }
    public void updFileList() {
        new Thread(() -> { // Again to not freeze the UI while we're fetching files
            try {
                // Get current path and then get file list from it
                String cdir = file.pwd();
                List<FileList> filelist = file.ls(); 

                javax.swing.SwingUtilities.invokeLater(() -> {
                    fieldPath.setText(cdir);
                    
                    // Insert filelist as rows to the table
                    javax.swing.table.DefaultTableModel tf = (javax.swing.table.DefaultTableModel) tableFile.getModel();
                    tf.setRowCount(0); // Clear old list
                    for (FileList f : filelist) {
                        tf.addRow(new Object[]{ f.getName(), f.getSize(), f.getDate() });
                    }
                });
            } catch (Exception ex) {
                javax.swing.SwingUtilities.invokeLater(() -> {
                    javax.swing.JOptionPane.showMessageDialog(this, ex.getMessage());
                });
            }
        }).start();
    }
    private void clearFileList() {
        javax.swing.table.DefaultTableModel tf = (javax.swing.table.DefaultTableModel) tableFile.getModel();
        tf.setRowCount(0);
    }

